	@Test
	@Timeout(30)
	void durablePostReadyCacheCaptureFollowsTheBoundedRetirementBatch() throws Exception {
		seedRetirement();
		AtomicBoolean capturedPendingRetirements = new AtomicBoolean();
		AtomicBoolean captureStarted = new AtomicBoolean();
		LmdbSailStore.ValueStoreFactory values = (path, properties, config) -> new ValueStore(path, properties,
				config) {
			@Override
			void startValueOverlayWarmupAfterStoreInitialization() {
				capturedPendingRetirements.set(hasRetiredIds());
				captureStarted.set(true);
				super.startValueOverlayWarmupAfterStoreInitialization();
			}
		};
		try (LmdbSailStore owner = new LmdbSailStore(directory, new StoreProperties(directory),
				config(true).setAsyncValueCleanup(false), false, values, TripleStore::new)) {
			owner.startBackgroundMaintenanceAfterInitialization();
			joinPostReadyInitializer();
			assertThat(captureStarted.get()).isTrue();
			assertThat(capturedPendingRetirements.get())
					.as("bounded retirement publication must finish before cache snapshot capture")
					.isFalse();
			assertThat(owner.postReadyMaintenanceStatus()).isEqualTo("READY");
		}
	}

	private static void joinPostReadyInitializer() throws InterruptedException {
		for (Thread helper : Thread.getAllStackTraces().keySet()) {
			if (helper.getName().equals("LmdbStore-PostReady")) {
				helper.join(TimeUnit.SECONDS.toMillis(10));
				assertThat(helper.isAlive()).as("post-ready initializer has completed").isFalse();
			}
		}
	}

	@Test
	@Timeout(30)
	void failedPostReadyWarmupPreservesAuthoritativeOwnerResources() throws Exception {
		Properties original = System.getProperties();
		Properties refusingWarmup = new Properties();
		refusingWarmup.putAll(original);
		Properties failing = new Properties(refusingWarmup) {
			@Override
			public String getProperty(String key) {
				if (BUDGET_PROPERTY.equals(key)) {
					throw new SecurityException("controlled warmup property refusal");
				}
				return super.getProperty(key);
			}
		};
		AtomicReference<ValueStore> openedValues = new AtomicReference<>();
		LmdbStoreConfig config = config(true);
		StoreProperties properties = new StoreProperties(directory);
		LmdbStoreFormat format = LmdbStoreFormat.fromProperties(properties, config);
		LmdbSailStore owner = null;
		try {
			owner = new LmdbSailStore(directory, properties, config, false,
					format, QueryExecutionPolicy.of(false), null,
					values -> {
						openedValues.set(values);
						System.setProperties(failing);
					});
			owner.startBackgroundMaintenanceAfterInitialization();
			joinPostReadyInitializer();
			assertThat(owner.postReadyMaintenanceStatus()).startsWith("FAILED:")
					.contains("controlled warmup property refusal");
			try (var read = openedValues.get().getTxnManager().createReadTxn()) {
				assertThat(read.get()).as("optional cache failure retains an open authoritative dictionary")
						.isNotZero();
			}
		} finally {
			System.setProperties(original);
			if (owner != null) {
				owner.close();
			}
		}
		assertThatThrownBy(() -> openedValues.get().getTxnManager().createReadTxn())
				.as("normal owner close must release the authoritative dictionary")
				.isInstanceOf(IOException.class)
				.hasMessage("Transaction manager is closed");

		// This deliberately metadata-free fixture owns its transient descriptor; reopening must supply it too.
		LmdbSailStore reopened = new LmdbSailStore(directory, properties, config, false,
				format, QueryExecutionPolicy.of(false));
		try {
			assertThat(lookupScope(reopened.valueStore())).isNotNull();
		} finally {
			reopened.close();
		}
	}

	@Test
	@Timeout(30)
	void ownerCloseStopsItsWarmupAndReleasesOverlayReservations() throws Exception {
		// This test owns warmup cancellation, not the separate cleanup-versus-warmup invalidation race.
		// A live-only seed keeps default async cleanup enabled without racing pending retirement.
		LmdbStore seed = new LmdbStore(directory, config(false));
		seed.init();
		try {
			try (NotifyingSailConnection writer = seed.getConnection()) {
				writer.begin();
				writer.addStatement(KEEPER, PREDICATE, VF.createLiteral("kept"));
				writer.commit();
			}
		} finally {
			seed.shutDown();
		}
		long retainedBefore = OverlayMemoryBudget.configuredShared().stats().used();
		CountDownLatch scanStarted = new CountDownLatch(1);
		CountDownLatch releaseScan = new CountDownLatch(1);
		LmdbStoreConfig config = config(true);
		StoreProperties properties = LmdbOwningTestStoreMetadata.open(directory, config);
		LmdbSailStore owner = new LmdbSailStore(directory, properties, config, false,
				LmdbStoreFormat.resolve(directory, properties, config), QueryExecutionPolicy.of(false), () -> {
					scanStarted.countDown();
					await(releaseScan);
				});
		AtomicReference<Throwable> failure = new AtomicReference<>();
		Thread close = new Thread(() -> {
			try {
				owner.close();
			} catch (Throwable e) {
				failure.set(e);
			}
		}, "owner-overlay-close-test");
		try {
			owner.startBackgroundMaintenanceAfterInitialization();
			assertThat(scanStarted.await(10, TimeUnit.SECONDS)).isTrue();
			close.start();
			releaseScan.countDown();
			close.join(TimeUnit.SECONDS.toMillis(10));
			assertThat(close.isAlive()).isFalse();
			assertThat(failure.get()).isNull();
			assertThat(owner.valueStore().isValueOverlayWarmupInProgress()).isFalse();
			assertThat(owner.valueStore().compressedValueOverlayStats()).isNull();
			assertThat(OverlayMemoryBudget.configuredShared().stats().used()).isEqualTo(retainedBefore);
		} finally {
			releaseScan.countDown();
			if (close.getState() == Thread.State.NEW) {
				owner.close();
			} else {
				close.join(TimeUnit.SECONDS.toMillis(10));
			}
		}
	}

	private void seedRetirement() throws Exception {
		// Only the seed requires a persisted durable intent; reopened owners exercise the default mode.
		LmdbStore store = new LmdbStore(directory, config(false).setAsyncValueCleanup(false));
		store.init();
		try {
			// Finish the seed owner's startup recovery before creating the retirement this test preserves.
			// Otherwise its post-ready worker can drain that new intent after the pinned reader releases it.
			LmdbGcTestMaintenance.awaitPostReady(store);
			try (NotifyingSailConnection writer = store.getConnection()) {
				writer.begin();
				writer.addStatement(KEEPER, PREDICATE, VF.createLiteral("kept"));
				writer.addStatement(RETIRED, PREDICATE, VF.createLiteral("removed"));
				writer.commit();
			}
			try (NotifyingSailConnection reader = store.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				try (var statements = reader.getStatements(RETIRED, PREDICATE, null, false)) {
					assertThat(statements.hasNext()).isTrue();
				}
				try (NotifyingSailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.NONE);
					writer.removeStatements(RETIRED, PREDICATE, null);
					writer.commit();
				}
				assertThat(store.getBackingStore().valueStore().hasRetiredIds()).isTrue();
				reader.commit();
			}
		} finally {
			store.shutDown();
		}
	}

	private LmdbStoreConfig config(boolean overlay) {
		// Bounded liveness probes require every referenced position to have a leading index.
		return new LmdbStoreConfig("spoc,posc,ospc").setInlineLiterals(false).setValueOverlayEnabled(overlay);
	}

	private void seedPersistedUnusedValue() throws Exception {
		// Standalone dictionary close has no TripleStore liveness checker, so normal GC leaves a durable unused ID.
		ValueStore values = new ValueStore(new File(directory, "values"), new StoreProperties(directory),
				config(false));
		try {
			values.startTransaction(true);
			long id = values.storeValue(VF.createBNode("pending-unused"));
			values.commit();
			values.startTransaction(true);
			values.gcIds(new HashSet<>(Set.of(id)), new HashSet<>());
			values.commit();
		} finally {
			values.close();
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			assertThat(latch.await(10, TimeUnit.SECONDS)).as("controlled startup interleaving").isTrue();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError(e);
		}
	}

	private static Object lookupScope(ValueStore values) {
		try {
			return values.valueLookupScope();
		} catch (IOException e) {
			throw new AssertionError(e);
		}
	}
